"""Generate readable managed HQ pixel recipes from the native pattern tables."""

import argparse
from pathlib import Path
import re


def generate(root):
    source = (root / "src" / "video_scale_hqNx.c").read_text(encoding="utf-8")
    result = [
        "/*",
        " * OpenTyrian HQ scalers, Copyright (C) 2003 MaxSt;",
        " * Copyright (C) 2007-2010 The OpenTyrian Development Team.",
        " * Distributed under the GNU General Public License, version 2 or later.",
        " * Generated by tools/generate_hq_kernels.py; edit the generator, not this file.",
        " */",
        "",
        "namespace OpenTyrian.Core;",
        "",
        "public static partial class HqVideoScaler",
        "{",
    ]
    for factor in (2, 3, 4):
        start = source.index(f"void hq{factor}x_32(SDL_Surface *src_surface, SDL_Texture *dst_texture)\n{{")
        macros = dict(re.findall(r"^#define (PIXEL\w+) +(.+)$", source[:start], re.MULTILINE))
        body = source[start:]
        body = body[body.index("switch (pattern)"):]
        body = body[:body.index("src++;")].strip()
        grammar = r"case \d+:|break;|if \(diff\(w\[\d\], w\[\d\]\)\)|else|[{}]|PIXEL\w+"
        tokens = re.findall(grammar, body)
        remaining = re.sub(grammar, "", body.replace("switch (pattern)", ""))
        if remaining.strip():
            raise ValueError(f"Unsupported HQ{factor}x pattern syntax: {remaining.strip()}")
        if not tokens or len(re.findall(r"case \d+:", body)) != 256:
            raise ValueError(f"Expected 256 pattern cases for HQ{factor}x.")
        result.append(f"    private static void Pattern{factor}(int pattern, Span<uint> output, int pitch, ReadOnlySpan<uint> c, ReadOnlySpan<uint> yuv)")
        result.append("    {")
        result.append("        switch (pattern)")
        depth = 2
        for token in tokens:
            if token == "}":
                depth -= 1
            indentation = depth + (1 if depth >= 4 or (depth == 3 and token in ("{", "}")) else 0)
            indent = "    " * indentation
            if token.startswith("PIXEL"):
                macro = macros[token]
                row, column = map(int, re.search(r"PIXEL(?:4_)?(\d)(\d)", token).groups())
                colors = re.findall(r"c\[(\d)\]", macro)
                interpolation = re.search(r"interp(\d+)\(", macro)
                value = f"c[{colors[0]}]"
                if interpolation:
                    arguments = ", ".join(f"c[{color}]" for color in colors)
                    value = f"Interpolate({interpolation[1]}, {arguments})"
                result.append(f"{indent}output[{row} * pitch + {column}] = {value};")
            elif token.startswith("if"):
                first, second = re.findall(r"w\[(\d)\]", token)
                result.append(f"{indent}if (Different(yuv[{first}], yuv[{second}]))")
            else:
                result.append(indent + token)
            if token == "{":
                depth += 1
        if depth != 2:
            raise ValueError(f"Unbalanced HQ{factor}x pattern blocks.")
        result.append("    }")
        result.append("")
    result.append("}")
    return "\n".join(result) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    output = generate(Path(__file__).resolve().parents[1])
    if args.check:
        if args.output.read_text(encoding="utf-8") != output:
            raise ValueError("Managed HQ kernels differ from the native pattern tables.")
    else:
        args.output.write_text(output, encoding="utf-8")


if __name__ == "__main__":
    main()
